package com.drivemanager.storagehub.tag;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="tags") public class Tag { @Id private UUID id; @Column(name="owner_id") private UUID ownerId; private String name; @Column(name="normalized_name") private String normalizedName; private String color; @Column(name="created_at") private Instant createdAt; @Column(name="updated_at") private Instant updatedAt; protected Tag(){} Tag(UUID o,String n,String nn,String c){id=UUID.randomUUID();ownerId=o;name=n;normalizedName=nn;color=c;createdAt=updatedAt=Instant.now();} void rename(String n,String nn,String c){name=n;normalizedName=nn;color=c;updatedAt=Instant.now();} public UUID getId(){return id;} public UUID getOwnerId(){return ownerId;} public String getName(){return name;} public String getColor(){return color;} }
